import re, subprocess, pathlib, shutil, os
base = pathlib.Path('/app/input.tex').read_text()
main = pathlib.Path('/app/main.tex').read_text()
lines = pathlib.Path('/app/synonyms.txt').read_text().splitlines()
families = {}
for line in lines:
    words=[w.strip() for w in line.split(',')]
    for w in words:
        families[w]=words
matches=[]
for m in re.finditer(r'(?<![A-Za-z])([A-Za-z]+)(?![A-Za-z])', base):
    w=m.group(1)
    if w in families:
        matches.append((w,m.start(),m.end()))
root=pathlib.Path('/tmp/latex-search')
if root.exists(): shutil.rmtree(root)
root.mkdir()
(root/'main.tex').write_text(main)

def test(text, label):
    (root/'input.tex').write_text(text)
    p=subprocess.run(['pdflatex','-interaction=nonstopmode','-halt-on-error','-file-line-error','-jobname='+label,'main.tex'],cwd=root,text=True,capture_output=True,timeout=10)
    log=p.stdout+p.stderr
    vals=[float(x) for x in re.findall(r'Overfull \\hbox \(([0-9.]+)pt too wide',log)]
    return p.returncode, len(vals), sum(vals), vals
base_result=test(base,'base')
print('base',base_result)
results=[]
for idx,(w,s,e) in enumerate(matches):
    for alt in families[w]:
        if alt==w: continue
        text=base[:s]+alt+base[e:]
        try:
            r=test(text,f'c{idx:03d}')
        except Exception as ex:
            print('ERR',idx,w,alt,ex); continue
        results.append((r[1],r[2],idx,w,alt,r[3]))
for row in sorted(results)[:40]: print(row)
print('matches',len(matches))
