use strict;
use warnings;
use File::Path qw(remove_tree make_path);

my $base = do { local $/; open my $f, '<', '/app/input.tex' or die $!; <$f> };
my $main = do { local $/; open my $f, '<', '/app/main.tex' or die $!; <$f> };
my %fam;
open my $sf, '<', '/app/synonyms.txt' or die $!;
while (<$sf>) {
    chomp;
    my @w = map { s/^\s+|\s+$//gr } split /,/;
    for my $w (@w) { $fam{$w} = \@w; }
}
my @matches;
while ($base =~ /(?<![A-Za-z])([A-Za-z]+)(?![A-Za-z])/g) {
    my $w = $1;
    push @matches, [$w, $-[1], $+[1]] if exists $fam{$w};
}
my $root = '/tmp/latex-search';
remove_tree($root) if -e $root;
make_path($root);
open my $mf, '>', "$root/main.tex" or die $!;
print $mf $main;
close $mf;

sub total { my $s = 0; $s += $_ for @_; return $s; }
sub test {
    my ($text, $label) = @_;
    open my $f, '>', "$root/input.tex" or die $!;
    print $f $text;
    close $f;
    my $log = "$root/$label.out";
    system("cd $root && pdflatex -interaction=nonstopmode -halt-on-error -file-line-error -jobname=$label main.tex >$log 2>&1");
    open my $lf, '<', $log or die $!;
    local $/;
    my $x = <$lf>;
    my @v = ($x =~ /Overfull.*?\(([0-9.]+)pt too wide/g);
    return (scalar @v, total(@v), join(',', @v));
}

my @b = test($base, 'base');
print "base @b\n";
my @res;
for my $i (0 .. $#matches) {
    my ($w, $s, $e) = @{$matches[$i]};
    for my $alt (@{$fam{$w}}) {
        next if $alt eq $w;
        my $text = substr($base, 0, $s) . $alt . substr($base, $e);
        my @r = test($text, sprintf('c%03d', $i));
        push @res, [$r[0], $r[1], $i, $w, $alt, $r[2]];
    }
}
@res = sort { $a->[0] <=> $b->[0] || $a->[1] <=> $b->[1] } @res;
for my $r (@res[0 .. ($#res < 49 ? $#res : 49)]) { print join(' ', @$r), "\n"; }
print "matches ", scalar @matches, "\n";
PERL
